__d(function(e,i,t,a,o,n,r){o.exports={version:"2.0",board:"Karnataka State Board / NCERT",grade:7,subject:"Mathematics",textbook:"Mathematics \u2014 Textbook for Class VII",chapter_number:2,chapter_title:"Fractions and Decimals",quiz_type:"MCQ only",mcqs:[{id:"mcq01",difficulty:"Easy",question:"What is the improper fraction form of 4\u2157?",options:["A) 22/5","B) 23/5","C) 17/5","D) 21/5"],correct_answer:"B) 23/5",explanation:"4\u2157 = (4\xd75 + 3)/5 = (20+3)/5 = 23/5. Formula: Whole \xd7 Denominator + Numerator, over Denominator."},{id:"mcq02",difficulty:"Easy",question:"What is the reciprocal of 7/3?",options:["A) 7/3","B) 3/7","C) \u22123/7","D) 21"],correct_answer:"B) 3/7",explanation:"Reciprocal of a/b = b/a. Reciprocal of 7/3 = 3/7. Check: 7/3 \xd7 3/7 = 21/21 = 1 \u2713."},{id:"mcq03",difficulty:"Easy",question:"Find: (2/3) \xd7 (9/4)",options:["A) 3/2","B) 18/12","C) 8/27","D) 6/7"],correct_answer:"A) 3/2",explanation:"(2/3) \xd7 (9/4) = 18/12 = 3/2. Cancel before multiplying: 2 and 4 share factor 2 \u2192 1/3 \xd7 9/2; then 9 and 3 share 3 \u2192 1/1 \xd7 3/2 = 3/2."},{id:"mcq04",difficulty:"Easy",question:"Find: (5/6) \xf7 (10/3)",options:["A) 1/4","B) 4","C) 25/18","D) 50/18"],correct_answer:"A) 1/4",explanation:"KCF: (5/6) \xf7 (10/3) = (5/6) \xd7 (3/10) = 15/60 = 1/4. Cancel: 5 and 10 share 5 \u2192 1/6 \xd7 3/2; 3 and 6 share 3 \u2192 1/2 \xd7 1/2 = 1/4."},{id:"mcq05",difficulty:"Easy",question:"Find \xbe of 64.",options:["A) 16","B) 48","C) 24","D) 32"],correct_answer:"B) 48",explanation:"'Of' means multiply. \xbe of 64 = \xbe \xd7 64 = (3\xd764)/4 = 192/4 = 48."},{id:"mcq06",difficulty:"Easy",question:"What is 0.6 \xd7 0.3?",options:["A) 1.8","B) 0.18","C) 0.018","D) 18"],correct_answer:"B) 0.18",explanation:"6 \xd7 3 = 18. Decimal places: 1+1 = 2. So 0.18. Note: 0.6 \xd7 0.3 is NOT 1.8 \u2014 that's a common error of adding instead of counting decimal places correctly."},{id:"mcq07",difficulty:"Easy",question:"Find: 5.37 \xd7 100",options:["A) 53.7","B) 537","C) 5370","D) 0.537"],correct_answer:"B) 537",explanation:"Multiplying by 100: shift the decimal point 2 places to the RIGHT. 5.37 \u2192 537. (The decimal moves right: 5.37 \u2192 53.7 \u2192 537.)"},{id:"mcq08",difficulty:"Easy",question:"Find: 8.4 \xf7 10",options:["A) 84","B) 840","C) 0.84","D) 0.084"],correct_answer:"C) 0.84",explanation:"Dividing by 10: shift the decimal 1 place to the LEFT. 8.4 \u2192 0.84."},{id:"mcq09",difficulty:"Easy",question:"Which of the following gives a terminating decimal?",options:["A) 1/3","B) 2/7","C) 3/8","D) 5/6"],correct_answer:"C) 3/8",explanation:"3/8 = 0.375 \u2014 terminates. 8 = 2\xb3, has only 2 as prime factor \u2192 terminating. 1/3 = 0.333\u2026, 2/7 = 0.285714\u2026, 5/6 = 0.8333\u2026 \u2014 all recurring, because their denominators have prime factors other than 2 and 5."},{id:"mcq10",difficulty:"Easy",question:"A ribbon of 4\xbd m is cut into pieces of \xbe m each. How many pieces are obtained?",options:["A) 5","B) 6","C) 3","D) 9/2"],correct_answer:"B) 6",explanation:"4\xbd \xf7 \xbe = (9/2) \xf7 (3/4) = (9/2) \xd7 (4/3) = 36/6 = 6 pieces."},{id:"mcq11",difficulty:"Moderate",question:"Find: 1\u2154 \xd7 2\xbc",options:["A) 3\xbe","B) 15/4","C) 2\u2154","D) 3\xbd"],correct_answer:"A) 3\xbe",explanation:"1\u2154 = 5/3. 2\xbc = 9/4. (5/3) \xd7 (9/4) = 45/12 = 15/4 = 3\xbe. Both A and B are the same value (15/4 = 3\xbe) \u2014 but 3\xbe as a mixed number is the fully simplified form typically expected."},{id:"mcq12",difficulty:"Moderate",question:"Find: 2\xbd \xf7 1\u2154",options:["A) 3/2","B) 25/24","C) 3/2","D) 1\xbd"],correct_answer:"D) 1\xbd",explanation:"2\xbd = 5/2. 1\u2154 = 5/3. (5/2) \xf7 (5/3) = (5/2) \xd7 (3/5) = 15/10 = 3/2 = 1\xbd."},{id:"mcq13",difficulty:"Moderate",question:"Evaluate: 1.25 \xd7 0.04",options:["A) 0.5","B) 0.05","C) 5","D) 0.005"],correct_answer:"B) 0.05",explanation:"125 \xd7 4 = 500. Decimal places: 2+2 = 4. 500 with 4 decimal places \u2192 0.0500 = 0.05."},{id:"mcq14",difficulty:"Moderate",question:"Find: 4.68 \xf7 0.6",options:["A) 7.8","B) 0.78","C) 78","D) 0.078"],correct_answer:"A) 7.8",explanation:"Multiply both by 10: 46.8 \xf7 6 = 7.8. The decimal in the divisor (0.6) is removed by multiplying both by 10, giving 46.8 \xf7 6 = 7.8."},{id:"mcq15",difficulty:"Moderate",question:"A school has 800 students. \u215d are from Karnataka. How many students are from Karnataka?",options:["A) 400","B) 500","C) 600","D) 640"],correct_answer:"B) 500",explanation:"\u215d of 800 = \u215d \xd7 800 = (5\xd7800)/8 = 4000/8 = 500 students."},{id:"mcq16",difficulty:"Moderate",question:"Find the value of: (0.2)\xb3",options:["A) 0.6","B) 0.008","C) 0.08","D) 8"],correct_answer:"B) 0.008",explanation:"(0.2)\xb3 = 0.2 \xd7 0.2 \xd7 0.2. 0.2 \xd7 0.2 = 0.04 (1+1=2 places). 0.04 \xd7 0.2 = 0.008 (2+1=3 places). Answer: 0.008."},{id:"mcq17",difficulty:"Moderate",question:"Which expression equals 3/4 \xf7 6?",options:["A) 3/4 \xd7 6","B) 3/4 \xd7 1/6","C) 4/3 \xd7 6","D) 6 \xd7 4/3"],correct_answer:"B) 3/4 \xd7 1/6",explanation:"Dividing by a whole number = multiplying by its reciprocal. 3/4 \xf7 6 = 3/4 \xd7 1/6 = 3/24 = 1/8."},{id:"mcq18",difficulty:"Moderate",question:"A factory produces 1245.6 kg of goods per day. How much does it produce in 0.5 days?",options:["A) 6228","B) 622.8","C) 62.28","D) 2491.2"],correct_answer:"B) 622.8",explanation:"1245.6 \xd7 0.5 = 12456 \xd7 5 \xf7 1000 = 62280/100... let's recalculate: 12456 \xd7 5 = 62280, decimal places 1+1=2, so 622.80 = 622.8."},{id:"mcq19",difficulty:"Advanced",question:"A tank is \u2157 full. After adding 12 litres it becomes \u2158 full. What is the capacity of the tank?",options:["A) 50 litres","B) 60 litres","C) 45 litres","D) 30 litres"],correct_answer:"B) 60 litres",explanation:"Fraction added = \u2158 \u2212 \u2157 = \u2155 of tank = 12 litres. Full tank = 12 \xd7 5 = 60 litres."},{id:"mcq20",difficulty:"Advanced",question:"If 2.5 \xd7 p = 0.075, find p.",options:["A) 0.3","B) 0.03","C) 3","D) 0.003"],correct_answer:"B) 0.03",explanation:"p = 0.075 \xf7 2.5. Multiply both by 10: 0.75 \xf7 25. Multiply both by 4: 3 \xf7 100 = 0.03. Or: 75 \xf7 2500 = 3/100 = 0.03."}]}},2771,[]);